// Vertriebsakademie – Content-Modul
// Zentrale Wissens- und Skriptbibliothek für den Sidebar-Bereich „Vertriebsakademie".

export interface AkademieLink { label: string; to: string; hinweis?: string; external?: boolean; }
export interface AkademieSkript { titel: string; kontext?: string; text: string; /** Verkaufspsychologische Erklärung: warum das Skript / die Frage / der Satz so aufgebaut ist */ warum?: string; /** Optionale, kontextspezifische Überschrift für den „Warum"-Kasten. Falls leer, wird sie automatisch aus dem Skript-Inhalt abgeleitet. */ warumTitel?: string; }
export interface AkademieEinwand {
  einwand: string;
  technik?: string;
  antwort: string;
  /** Verkaufspsychologische Erklärung: warum die Antwort so wirkt. Erscheint zuklappbar unter der Antwort, genau wie beim Skript. */
  warum?: string;
  /** Optionale, eigene Überschrift für den „Warum"-Kasten. Ohne Angabe „Warum diese Antwort so wirkt". */
  warumTitel?: string;
}
export interface AkademieUebung {
  id: string;
  titel: string;
  beschreibung: string;
  xp?: number;
  /** Advanced Challenge (nur für erfahrene Partner sichtbar in Profi-Ansicht). */
  advanced?: boolean;
  /** Antwort-Typ: keine = nur Checkbox, text = einzeilig, textarea = mehrzeilig, liste = Bullet-Liste */
  antwortTyp?: "keine" | "text" | "textarea" | "liste";
  /** Label über dem Antwortfeld */
  antwortLabel?: string;
  /** Platzhalter im Feld */
  antwortPlaceholder?: string;
  /** Mindest-Zeichenanzahl, damit XP + Erledigt-Marker gesetzt werden (Default 20) */
  mindestZeichen?: number;
}
/** Gold-Nugget-Baustein: kompaktes Profi-Wissen pro Section (goldene Box). */
export interface AkademieGoldNugget {
  titel: string;
  text: string;
  /** Optionales Extra-Skript zum Kopieren. */
  skript?: AkademieSkript;
  /** Zusätzliche Bullet-Points. */
  bullets?: string[];
}

// ============================================================================
// Visualisierungs-Bausteine – kleine Charts, Rechenbeispiele, Timelines etc.
// Ziel: Kapitel lebendig machen, ohne den Content-Fluss zu brechen.
// ============================================================================

/** Farbige KPI-Kachel (bis zu 4 in einer Reihe). */
export interface AkademieKpi {
  label: string;
  wert: string;
  hinweis?: string;
  farbe?: "primary" | "emerald" | "amber" | "rose" | "sky" | "indigo";
}

/** Rechenbeispiel – zeilenweise Aufschlüsselung mit Summenzeile. */
export interface AkademieBeispielrechnung {
  titel: string;
  untertitel?: string;
  zeilen: {
    label: string;
    wert: string;
    /** Rechenoperator, der links neben dem Wert erscheint. */
    op?: "+" | "−" | "×" | "÷" | "=" | "→";
    /** Zeile visuell hervorheben (Trennlinie + Bold). */
    ergebnis?: boolean;
    /** Kleiner Erklärtext unter der Zeile. */
    hinweis?: string;
  }[];
  fazit?: string;
}

/** Horizontal-Barchart mit Prozent- oder Absolut-Werten. */
export interface AkademieBarchart {
  titel: string;
  untertitel?: string;
  einheit?: string;
  daten: { label: string; wert: number; hinweis?: string; hervorheben?: boolean }[];
  /** Falls gesetzt: y-Achse endet bei diesem Wert (statt max). */
  maxWert?: number;
}

/** Donut/Pie mit Segmenten. */
export interface AkademieDonut {
  titel: string;
  untertitel?: string;
  daten: { label: string; wert: number; farbe?: string }[];
  zentrumLabel?: string;
  zentrumWert?: string;
}

/** Timeline mit Meilensteinen. */
export interface AkademieTimeline {
  titel: string;
  schritte: {
    label: string;
    dauer?: string;
    beschreibung?: string;
    status?: "start" | "trigger" | "ziel";
  }[];
}

/** Vergleich zweier Optionen (A/B nebeneinander). */
export interface AkademieVergleich {
  titel: string;
  untertitel?: string;
  optionA: { label: string; punkte: string[]; ergebnis?: string; badge?: string };
  optionB: { label: string; punkte: string[]; ergebnis?: string; badge?: string };
  fazit?: string;
}

export interface AkademieVisual {
  /** Nur in der Profi-Ansicht sichtbar. */
  advanced?: boolean;
  kpis?: AkademieKpi[];
  beispielrechnung?: AkademieBeispielrechnung;
  barchart?: AkademieBarchart;
  donut?: AkademieDonut;
  timeline?: AkademieTimeline;
  vergleich?: AkademieVergleich;
}

export interface AkademieSection {
  id: string;
  ueberschrift: string;
  intro?: string;
  absaetze?: string[];
  bullets?: string[];
  profiTipp?: string;
  /** Blaue „Für Quereinsteiger"-Erklärbox: Fachbegriffe entwirren, in Alltagssprache erklären */
  quereinsteigerHinweis?: string;
  /** Goldene „Gold-Nugget für Profis"-Box mit Advanced-Wissen. */
  goldNugget?: AkademieGoldNugget;
  skripte?: AkademieSkript[];
  einwaende?: AkademieEinwand[];
  links?: AkademieLink[];
  checkliste?: string[];
  uebungen?: AkademieUebung[];
  /** Grafiken, Charts, Rechenbeispiele – erscheinen zwischen Absätzen und Skripten. */
  visuals?: AkademieVisual[];
  /** Prüfbare Aufgaben: Quiz, Sortieren, Zuordnen, Rechnen, Szenario. */
  aufgaben?: AkademieAufgabe[];
  /** Inline-Iframe-Vorschau einer internen Seite (z. B. Beratungspräsentation) */
  praesentationEmbed?: {
    url: string;
    label: string;
    hoehe?: number;
    oeffnenLabel?: string;
  };
  /**
   * Trainings-Cockpit für die Beratungspräsentation MOREImmo:
   * Vorschau links, scrollsynchrones Sprechskript rechts.
   */
  trainingsCockpit?: boolean;
}

// ============================================================================
// Prüfbare Aufgaben
//
// Grundregel: Jede Aufgabe trägt ihre Lösung im Inhalt. Ausgewertet wird durch
// Vergleich im Browser, ohne KI und ohne Netzwerkaufruf. Punkte gibt es nur
// für richtige Antworten, nie fürs Anklicken.
//
// Das Feld `pfad` steuert, wer die Aufgabe sieht:
//   "beide"          – in jedem Lernpfad sichtbar
//   "quereinsteiger" – nur im Quereinsteiger-Pfad (und in "alle")
//   "profi"          – nur im Profi-Pfad (und in "alle")
// Typischerweise liegt zu einem Thema eine leichte Variante für Quereinsteiger
// und eine harte für Profis nebeneinander.
// ============================================================================

import type { AkademieWahrFalschAufgabe } from "@/lib/vertriebsakademieAufgabenTypen";

export type AufgabenPfad = "beide" | "quereinsteiger" | "profi";

interface AufgabeBasis {
  id: string;
  /** Überschrift der Aufgabenkarte. */
  titel: string;
  /** Optionale Aufgabenstellung über dem Inhalt. */
  hinweis?: string;
  pfad?: AufgabenPfad;
  /** Punkte bei richtiger Lösung im ersten Versuch. Default 10. */
  punkte?: number;
  /** Zeitlimit in Sekunden. Ohne Angabe kein Zeitdruck. */
  zeitlimitSek?: number;
}

/** Multiple Choice mit genau einer richtigen Option. */
export interface AkademieQuizAufgabe extends AufgabeBasis {
  typ: "quiz";
  fragen: {
    frage: string;
    optionen: string[];
    /** Index der richtigen Option in `optionen`. */
    korrekt: number;
    /** Auflösung, die nach der Antwort erscheint. */
    aufloesung: string;
    /** Abschnitts-ID im selben Kapitel, zu der die Auflösung springt. */
    sprungZuAbschnitt?: string;
  }[];
  /** true: Auflösung erst am Ende aller Fragen (Profi-Variante). */
  aufloesungAmEnde?: boolean;
}

/** Elemente in die richtige Reihenfolge bringen. */
export interface AkademieSortierAufgabe extends AufgabeBasis {
  typ: "sortieren";
  /** In der richtigen Reihenfolge notiert. Gemischt wird beim Rendern. */
  schritte: string[];
  /** true: erste und letzte Position sind vorgegeben (Quereinsteiger-Variante). */
  randVorgegeben?: boolean;
}

/** Begriffe den passenden Erklärungen zuordnen. */
export interface AkademieZuordnenAufgabe extends AufgabeBasis {
  typ: "zuordnen";
  paare: { links: string; rechts: string }[];
  /** Zusätzliche falsche Antwortkarten, nur für die Profi-Variante. */
  ablenker?: string[];
}

/** Zahl ausrechnen, Vergleich gegen einen Zielwert mit Toleranz. */
export interface AkademieRechenAufgabe extends AufgabeBasis {
  typ: "rechnen";
  fall: string;
  gesucht: string;
  zielwert: number;
  /** Zulässige Abweichung in Prozent. Default 1. */
  toleranzProzent?: number;
  einheit?: string;
  /** Rechenweg, dargestellt als vorhandene Beispielrechnung. */
  rechenweg: AkademieBeispielrechnung;
  /** true: Rechenweg erst nach dem Versuch sichtbar (Profi-Variante). */
  wegErstNachVersuch?: boolean;
}

/** Verzweigter Fall: Szene, Wahl, Konsequenz, nächste Szene. */
export interface AkademieSzenarioAufgabe extends AufgabeBasis {
  typ: "szenario";
  startSzene: string;
  szenen: {
    id: string;
    text: string;
    /** Ohne Optionen ist die Szene ein Ende. */
    optionen?: {
      text: string;
      /** ID der Folgeszene. Fehlt sie, endet der Fall hier. */
      weiterZu?: string;
      /** Konsequenz, die vor der nächsten Szene erscheint. */
      konsequenz?: string;
      /** Bewertung des Wegs: gut, tragfähig, schwach. */
      bewertung?: "gut" | "tragbar" | "schwach";
    }[];
    /** Abschlusstext, wenn die Szene ein Ende ist. */
    fazit?: string;
  }[];
}

/** Abwägungsfall ohne richtige Antwort, mit anonymer Verteilung im Team. */
export interface AkademieAbwaegungsfall {
  id: string;
  titel: string;
  fall: string;
  wege: { id: string; label: string; beschreibung: string }[];
  /** Ab wie vielen Antworten die Verteilung sichtbar wird. Default 8. */
  mindestAntworten?: number;
}

export type AkademieAufgabe =
  | AkademieQuizAufgabe
  | AkademieSortierAufgabe
  | AkademieZuordnenAufgabe
  | AkademieRechenAufgabe
  | AkademieSzenarioAufgabe
  | AkademieWahrFalschAufgabe;

export interface AkademieKapitel {
  slug: string;
  nummer: string;
  titel: string;
  kicker: string;
  teaser: string;
  ziel?: string;
  icon: "compass" | "flag" | "network" | "phone" | "presentation" | "building" | "banknote" | "scroll" | "gift" | "brain" | "rocket" | "book";
  placeholder?: boolean;
  sections: AkademieSection[];
  /**
   * Abschlusstest des Kapitels. Im Profi-Pfad zusätzlich als Freitest nutzbar,
   * also ohne das Kapitel vorher zu lesen.
   */
  abschlusstest?: {
    fragen: AkademieQuizAufgabe["fragen"];
    /** Bestehensquote in Prozent. Default 70. */
    bestehensquote?: number;
    /** Wie viele Fragen gezogen werden. Ohne Angabe alle. */
    anzahl?: number;
  };
  /** Abwägungsfall für den Profi-Pfad. */
  abwaegungsfall?: AkademieAbwaegungsfall;
}

/** Aufgaben eines Abschnitts, gefiltert nach Lernpfad. */
export function aufgabenFuerPfad(
  sec: AkademieSection,
  zielgruppe: "alle" | "quereinsteiger" | "profi",
): AkademieAufgabe[] {
  return (sec.aufgaben ?? []).filter((a) => {
    const pfad = a.pfad ?? "beide";
    if (pfad === "beide") return true;
    if (zielgruppe === "alle") return true;
    return pfad === zielgruppe;
  });
}

