export function getKapitelBySlug(slug: string): AkademieKapitel | undefined {
  return VERTRIEBSAKADEMIE_KAPITEL.find((k) => k.slug === slug);
}

export function getNextKapitel(slug: string): AkademieKapitel | undefined {
  const idx = VERTRIEBSAKADEMIE_KAPITEL.findIndex((k) => k.slug === slug);
  if (idx === -1 || idx === VERTRIEBSAKADEMIE_KAPITEL.length - 1) return undefined;
  return VERTRIEBSAKADEMIE_KAPITEL[idx + 1];
}

export function getPrevKapitel(slug: string): AkademieKapitel | undefined {
  const idx = VERTRIEBSAKADEMIE_KAPITEL.findIndex((k) => k.slug === slug);
  if (idx <= 0) return undefined;
  return VERTRIEBSAKADEMIE_KAPITEL[idx - 1];
}

