export interface EinwandEintrag {
  id: string;
  kategorie: EinwandKategorie;
  einwand: string;
  /** ID der Technik aus EINWAND_TECHNIKEN, die hier greift. */
  technik?: string;
  /**
   * Schritte des Erstgesprächsskripts, in denen dieser Einwand typischerweise
   * kommt. Damit kann die Schnellhilfe im Skript die passenden Einwände
   * einblenden, ohne dass der Partner die Bibliothek öffnen muss.
   */
  skriptSchritte?: string[];
  meintEigentlich: string;
  antwortKurz: string;
  antwortStory?: string;
  antwortZahlen?: string;
  falle: string;
  profiMove?: string;
  profiMoveLink?: { label: string; to: string };
  tags?: string[];
}

